interface.signature:
interface ThumbnailPerformance {
  contentId: string;
  thumbnailUrl?: string;
  style: ThumbnailStyle;
  impressions: number;
  clicks: number;
  ctr: number; // (clicks / impressions) * 100
  rank: number;
}

type ThumbnailStyle = 'text-heavy' | 'face' | 'action' | 'minimal' | 'before-after' | 'curiosity-gap' | 'unknown';

interface StylePerformance {
  style: ThumbnailStyle;
  videoCount: number;
  avgCtr: number;
  totalImpressions: number;
  totalClicks: number;
  confidence: 'high' | 'medium' | 'low';
  rank: number;
}
